func TestParseBlame(t *testing.T) {
	raw := `aaaa 1 1 2
author Alice
author-mail <alice@x>
author-time 100
summary s
filename f
	line one
aaaa 2 2
author Alice
author-mail <alice@x>
author-time 100
filename f
	line two
bbbb 3 3 1
author Bob Ünï
author-mail <bob@x>
author-time 300
filename f
	// Code generated by x. DO NOT EDIT.
`
	fb, err := ParseBlame(strings.NewReader(raw))
	if err != nil {
		t.Fatal(err)
	}
	if fb.Total != 3 || fb.Lines[Author{"Alice", "alice@x"}] != 2 || fb.Lines[Author{"Bob Ünï", "bob@x"}] != 1 {
		t.Errorf("counts wrong: %+v", fb)
	}
	if fb.LastTime != 300 {
		t.Errorf("LastTime = %d", fb.LastTime)
	}
	if !fb.Generated {
		t.Error("generated header within the first 5 lines should be detected")
	}
}

type memCache struct {
	mu   sync.Mutex
	m    map[string]FileBlame
	hits int
}

func (c *memCache) Get(p, b string) (FileBlame, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()
	fb, ok := c.m[p+"@"+b]
	if ok {
		c.hits++
	}
	return fb, ok
}

func (c *memCache) Put(p, b string, fb FileBlame) {
	c.mu.Lock()
	c.m[p+"@"+b] = fb
	c.mu.Unlock()
}

func TestBlameAllIntegration(t *testing.T) {
	ctx := context.Background()
	r := testutil.NewRepo(t)

	// Alice writes 10 lines; Bob rewrites 4 of them and adds 2.
	r.Write("a.txt", testutil.Lines("a", 10))
	r.Write("gen.go", "// Code generated by tool. DO NOT EDIT.\npackage x\n")
	r.Write("vendor/v.go", "package v\n")
	r.Write("go.sum", "x\n")
	r.Write("data.bin", "\x00\x01\x02\x03binary\x00")
	r.Write(".gitattributes", "attr.txt linguist-generated\n")
	r.Write("attr.txt", "generated via attr\n")
	r.Commit("Alice", "alice@example.com", day(1), "init")

	r.Write("a.txt", "a1\nBOB\nBOB\nBOB\nBOB\na6\na7\na8\na9\na10\nnew1\nnew2\n")
	r.Commit("Bob", "bob@example.com", day(2), "edit")

	f := NewFilter(nil, nil)
	files, err := ListFiles(ctx, r.Dir, "HEAD", f)
	if err != nil {
		t.Fatal(err)
	}
	var paths []string
	for _, tf := range files {
		paths = append(paths, tf.Path)
	}
	// .gitattributes itself, a.txt and gen.go (until content check) remain.
	want := map[string]bool{".gitattributes": true, "a.txt": true, "gen.go": true}
	if len(paths) != len(want) {
		t.Fatalf("files = %v", paths)
	}
	for _, p := range paths {
		if !want[p] {
			t.Errorf("unexpected file %q in %v", p, paths)
		}
	}

	cache := &memCache{m: map[string]FileBlame{}}
	var lastDone, lastTotal int
	var pm sync.Mutex
	opts := BlameOptions{Rev: "HEAD", Jobs: 2, Cache: cache, Filter: f,
		Progress: func(d, n int) { pm.Lock(); lastDone, lastTotal = d, n; pm.Unlock() }}
	res, err := BlameAll(ctx, r.Dir, files, opts)
	if err != nil {
		t.Fatal(err)
	}
	if _, ok := res["gen.go"]; ok {
		t.Error("generated file should be dropped")
	}
	if f.Allow("gen.go") {
		t.Error("generated file should be marked on the filter")
	}
	if lastDone != 3 || lastTotal != 3 {
		t.Errorf("progress = %d/%d", lastDone, lastTotal)
	}
	a := res["a.txt"]
	alice, bob := Author{"Alice", "alice@example.com"}, Author{"Bob", "bob@example.com"}
	if a.Total != 12 || a.Lines[alice] != 6 || a.Lines[bob] != 6 {
		t.Errorf("a.txt blame = %+v", a.Lines)
	}
	if got := a.SortedAuthors(); got[0] != alice && got[0] != bob {
		t.Errorf("sorted authors = %v", got)
	}

	// Second run must be served entirely from the cache.
	if _, err := BlameAll(ctx, r.Dir, files, opts); err != nil {
		t.Fatal(err)
	}
	if cache.hits != 3 {
		t.Errorf("cache hits = %d, want 3", cache.hits)
	}
}

func TestBlameIgnoreRevsAndMailmap(t *testing.T) {
	ctx := context.Background()
	r := testutil.NewRepo(t)
	r.Write(".mailmap", "Alice Real <alice@example.com> <old@example.com>\n")
	r.Write("a.txt", "x\ny\n")
	r.Commit("old-alice", "old@example.com", day(1), "init")
	r.Write("a.txt", "x\nY\n")
	reformat := r.Commit("Bob", "bob@example.com", day(2), "reformat")
	r.Write(".git-blame-ignore-revs", reformat+"\n")
	r.Commit("Bob", "bob@example.com", day(3), "add ignore file")

	files, err := ListFiles(ctx, r.Dir, "HEAD", NewFilter(nil, nil))
	if err != nil {
		t.Fatal(err)
	}
	res, err := BlameAll(ctx, r.Dir, files, BlameOptions{})
	if err != nil {
		t.Fatal(err)
	}
	a := res["a.txt"]
	t.Logf("blame lines: %+v", a.Lines)
	// A rewritten line (not a pure addition) goes back to the previous author
	// once the rewriting commit is ignored.
	for au := range a.Lines {
		if au.Name == "Bob" {
			t.Errorf("ignore-revs not honored: %+v", a.Lines)
		}
	}
}

func TestBlameContextCancel(t *testing.T) {
	r := testutil.NewRepo(t)
	r.Write("a.txt", "x\n")
	r.Commit("A", "a@x", day(1), "init")
	files, _ := ListFiles(context.Background(), r.Dir, "HEAD", NewFilter(nil, nil))
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	if _, err := BlameAll(ctx, r.Dir, files, BlameOptions{}); err == nil {
		t.Error("expected error from cancelled context")
	}
}
